import Papa from 'papaparse'
import { contentFingerprint, schemaFingerprint, type DatasetFingerprints } from './identity'
import type { LinkCheck } from './generate/base'

export type CsvRow = Record<string, string>

export interface CsvData {
  fileName: string
  fileSize: number
  columns: string[]
  rows: CsvRow[]
  /** Row-level problems PapaParse reported (e.g. wrong field count). */
  warnings: string[]
  /** Structure and exact-content hashes, used to recognise the dataset on re-upload. */
  fingerprints: DatasetFingerprints
  /** Set when the data is a fictional sample generated by AI rather than an uploaded file. */
  generatedBy?: {
    model: string
    generatedAt: string
    notes: string
    /** The dataset it was made to complement, and how well its claimed links really match. */
    basedOn?: { datasetId: string; name: string; linkChecks: LinkCheck[] }
  }
}

export const MAX_FILE_SIZE = 50 * 1024 * 1024 // 50 MB

export function isCsvFile(file: File): boolean {
  return file.name.toLowerCase().endsWith('.csv') || file.type === 'text/csv'
}

export async function parseCsv(file: File): Promise<CsvData> {
  const [parsed, content] = await Promise.all([
    parseRows(file),
    file.arrayBuffer().then(contentFingerprint),
  ])
  return { ...parsed, fingerprints: { schema: await schemaFingerprint(parsed.columns), content } }
}

function parseRows(file: File): Promise<Omit<CsvData, 'fingerprints'>> {
  return new Promise((resolve, reject) => {
    Papa.parse<CsvRow>(file, {
      header: true,
      skipEmptyLines: 'greedy',
      transformHeader: (header) => header.trim(),
      complete: (results) => {
        const columns = results.meta.fields ?? []
        if (columns.length === 0) {
          reject(new Error('The file has no header row.'))
          return
        }
        resolve({
          fileName: file.name,
          fileSize: file.size,
          columns,
          rows: results.data,
          warnings: results.errors.map((e) =>
            e.row !== undefined ? `Row ${e.row + 2}: ${e.message}` : e.message,
          ),
        })
      },
      error: (error) => reject(error),
    })
  })
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}
